INSERT INTO public.course (id, title, course_code, description, learning_outcomes, training_hours, assessment_hours, difficulty, mode_of_learning, course_type, status, class_status, is_skills_future_eligible, start_date, end_date, domain, course_fee, num_of_days, enrollment_status) VALUES (gen_random_uuid(), 'Generative AI for Business Professionals: ChatGPT, Media Synthesis, and Beyond', 'NTUC-LH-GAI-01', 'Build practical AI skills for work using ChatGPT, Copilot, and media synthesis platforms to enhance productivity across business functions.', 'Explain how gen-AI works; craft effective prompts; apply AI tools to business tasks; identify risks of AI-generated content; design a personal GenAI action plan.', 14, 2, 'Basic', 'Hybrid', 'WSQ', 'Published'::assessment_status, 'Confirmed', true, '2026-11-02'::date, '2026-11-06'::date, 'Data Analytics & AI', 1200.00, 5, 'Open') RETURNING id INTO v1;
INSERT INTO public.course_run (course_id, course_run_id, start_date, end_date, mode_of_learning, class_status) VALUES (v1, 'LH-GAI-2026-NOV-A', '2026-11-02'::date, '2026-11-06'::date, 'Physical', 'Confirmed') RETURNING id INTO r1a;
